@prefix df: <https://w3id.org/geolabs/ospd/data-formats/> .
@prefix gp: <https://geolabs.github.io/bblocks-generic-profiles/def/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://geolabs.github.io/bblocks-generic-profiles/def/implementation-profile/intersects/inputs/geometry1> ;
            sh:resultMessage "A representation must be a df:Representation of the bblocks-data-formats register." ;
            sh:resultPath gp:representation ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:ClassConstraintComponent ;
            sh:sourceShape [ sh:class df:Representation ;
                    sh:message "A representation must be a df:Representation of the bblocks-data-formats register." ;
                    sh:nodeKind sh:IRI ;
                    sh:path gp:representation ] ;
            sh:value <https://geolabs.github.io/bblocks-data-types/def/data-type/geometry> ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://geolabs.github.io/bblocks-generic-profiles/def/implementation-profile/intersects/inputs/geometry1> ;
            sh:resultMessage "A representation must realize a version of the role's dataType, or of a broader data type." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ a sh:SPARQLConstraint ;
                    sh:message "A representation must realize a version of the role's dataType, or of a broader data type." ;
                    sh:select """
            SELECT $this ?value WHERE {
                $this <https://geolabs.github.io/bblocks-generic-profiles/def/representation> ?value .
                $this <http://purl.org/dc/terms/type> ?dataType .
                FILTER NOT EXISTS {
                    ?value <https://w3id.org/ogc/rim/realizes> ?version .
                    ?version <https://w3id.org/ogc/rim/versionOf> ?concept .
                    ?dataType <http://www.w3.org/2004/02/skos/core#broader>* ?concept .
                }
            }
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape gp:RepresentationReferenceShape ;
            sh:value <https://geolabs.github.io/bblocks-data-types/def/data-type/geometry> ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms true .

